    @Test void relationVersionAdvanceInvalidatesOldGrantTargetsWithoutSourceCycleChange()throws Exception{var f=data();String request=fixed(f,"ROLE_GRANT",List.of(f.department()),null,true);String baseline=jdbc.queryForObject("SELECT baseline_id FROM change_target WHERE request_id=?",String.class,request),source=jdbc.queryForObject("SELECT source_id FROM change_target WHERE request_id=?",String.class,request);jdbc.update("UPDATE grant_baseline SET relation_version=1,row_version=row_version+1 WHERE id=?",baseline);var relation=new AffectedFacts.RelationChange(new GrantReader.Key(f.employee(),f.role(),f.company(),f.department()),source,baseline,0,1,null,null);invalidate(new RequestInvalidator.Changes(new AffectedFacts(List.of(),List.of(relation)),Set.of(),Set.of(),Set.of(),Map.of()));state(request,"INVALIDATED");}
