    @Test void exhaustedSourceCycleRejectsAtomicallyInsteadOfServerError()throws Exception{var f=data();String request=fixed(f,"ROLE_GRANT",List.of(f.department()),null,true);jdbc.update("UPDATE authorization_source SET source_epoch=?,source_version=? WHERE employee_id=?",ManagementInput.MAX_VERSION,ManagementInput.MAX_VERSION,f.employee());var in=new LinkedHashMap<>(input(f));in.put("systems",List.of(Map.of("systemId",f.system(),"expectedSourceEpoch",ManagementInput.MAX_VERSION,"expectedVersion",ManagementInput.MAX_VERSION)));var r=close(in,preview(in),id());assertThat(r.statusCode()).as(r.body()).isEqualTo(409);state(request,"PENDING");assertThat(count("SELECT source_epoch FROM authorization_source WHERE employee_id=?",f.employee())).isEqualTo(ManagementInput.MAX_VERSION);}
    @Test void replayRetainsCoverageRequiredByPreviouslyVisibleRequestCount()throws Exception{var f=data();var a=scoped(f,f.department());String second=id(),role=id();jdbc.update("INSERT INTO business_system(id,code,name,created_at) VALUES(?,?,'Fixture second system',UTC_TIMESTAMP(6))",second,second);jdbc.update("INSERT INTO business_role(id,code,name,company_id,system_id,state,configuration_version,created_at) VALUES(?,?,'Fixture second role',?,?,'EFFECTIVE',4,UTC_TIMESTAMP(6))",role,role,f.company(),second);jdbc.update("INSERT INTO scope_system(scope_id,system_id) VALUES(?,?)",a.scope(),second);var f2=new Data(f.employee(),f.company(),f.department(),f.other(),second,role);String first=fixed(f,"ROLE_GRANT",List.of(f.department()),null,false),other=fixed(f2,"ROLE_GRANT",List.of(f.department()),null,false);
        var content=json.readTree(jdbc.queryForObject("SELECT content FROM change_request WHERE id=?",String.class,first));var extra=json.readTree(jdbc.queryForObject("SELECT content FROM change_request WHERE id=?",String.class,other));((tools.jackson.databind.node.ArrayNode)content.path("items")).add(extra.path("items").get(0));jdbc.update("UPDATE change_request SET content=? WHERE id=?",json.writeValueAsString(content),first);jdbc.update("UPDATE change_target SET request_id=?,line_no=1 WHERE request_id=?",first,other);jdbc.update("UPDATE relation_change_claim SET request_id=? WHERE request_id=?",first,other);jdbc.update("UPDATE change_request SET state='PENDING',delivery_status='PENDING_SEND',submitted_version=1,submitted_at=UTC_TIMESTAMP(6),submitted_by_account_id=?,authority_type='GLOBAL',original_authority='{}',fixed_payload_bytes=?,content_digest=UNHEX(SHA2('multi-system-fixture',256)) WHERE id=?",account,new byte[]{9},first);
        var in=input(f);String p=scopedPreview(a,in),key=id();var r=scopedClose(a,in,p,key);assertThat(r.statusCode()).as(r.body()).isEqualTo(200);assertThat(body(r).path("invalidatedRequestCount").longValue()).isEqualTo(1);jdbc.update("DELETE FROM scope_system WHERE scope_id=? AND system_id=?",a.scope(),second);assertThat(scopedClose(a,in,p,key).statusCode()).isEqualTo(403);}
