    @Test void approvedAndFailedRequestsInvalidateWithoutDiscardingReliableApprovalHistory()throws Exception{for(boolean failed:List.of(false,true)){var f=data();String request=fixed(f,"ROLE_GRANT",List.of(f.department()),null,true),oa=jdbc.queryForObject("SELECT oa_instance_id FROM oa_outbox WHERE request_id=?",String.class,request),event=id();jdbc.update("INSERT INTO oa_link(request_id,oa_instance_id,oa_approval_id,accepted_at,created_at) VALUES(?,?,?,UTC_TIMESTAMP(6),UTC_TIMESTAMP(6))",request,oa,id());jdbc.update("INSERT INTO oa_callback_event(id,oa_instance_id,event_id,request_id,payload_digest,safe_payload,received_at) VALUES(?,?,?,?,UNHEX(REPEAT('00',32)),'{}',UTC_TIMESTAMP(6))",event,oa,id(),request);jdbc.update("INSERT INTO oa_final_result(request_id,first_event_id,decision,decided_at,comment,received_at) VALUES(?,?,'APPROVED',UTC_TIMESTAMP(6),'Fixture reliable approval',UTC_TIMESTAMP(6))",request,event);jdbc.update("UPDATE change_request SET state='APPROVED',delivery_status='LINKED',approval_result='APPROVED',execution_status='PENDING' WHERE id=?",request);jdbc.update("UPDATE oa_outbox SET task_state='DONE',lease_token=NULL,lease_until=NULL WHERE request_id=?",request);if(failed)jdbc.update("UPDATE change_request SET state='EXECUTION_FAILED',execution_status='FAILED',failure_code='EXECUTION_STORAGE_FAILURE',next_retry_at=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 5 MINUTE) WHERE id=?",request);var in=input(f);var r=close(in,preview(in),id());assertThat(r.statusCode()).as(r.body()).isEqualTo(200);state(request,"INVALIDATED");assertThat(jdbc.queryForObject("SELECT next_retry_at FROM change_request WHERE id=?",Object.class,request)).isNull();assertThat(jdbc.queryForObject("SELECT approval_result FROM change_request WHERE id=?",String.class,request)).isEqualTo("APPROVED");assertThat(jdbc.queryForObject("SELECT task_state FROM oa_outbox WHERE request_id=?",String.class,request)).isEqualTo("DONE");assertThat(count("SELECT COUNT(*) FROM oa_final_result WHERE request_id=?",request)).isEqualTo(1);}}
    @Test void secondSourceWriteFailureRollsBackEarlierWritesAndMaterializedZeros()throws Exception{var f=data();String another=id();jdbc.update("INSERT INTO business_system(id,code,name,created_at) VALUES(?,?,'Fixture atomic second system',UTC_TIMESTAMP(6))",another,another);String last=List.of(f.system(),another).stream().sorted().toList().getLast();var in=new LinkedHashMap<>(input(f));in.put("systems",List.of(Map.of("systemId",f.system(),"expectedSourceEpoch",0,"expectedVersion",0),Map.of("systemId",another,"expectedSourceEpoch",0,"expectedVersion",0)));String p=preview(in);db.execute("CREATE TRIGGER be26_fail_second BEFORE UPDATE ON authorization_source FOR EACH ROW BEGIN IF NEW.system_id='"+last+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='injected second source failure'; END IF; END");try{assertThat(close(in,p,id()).statusCode()).isEqualTo(500);}finally{db.execute("DROP TRIGGER be26_fail_second");}assertThat(count("SELECT COUNT(*) FROM authorization_source WHERE employee_id=?",f.employee())).isZero();}
    @Test void catchingInvalidatorFailureCannotCommitOuterEmployeeChange()throws Exception{var f=data();String request=fixed(f,"ROLE_GRANT",List.of(f.department()),null,true);db.execute("CREATE TRIGGER be26_caught_audit BEFORE INSERT ON audit_event FOR EACH ROW BEGIN IF NEW.event_type='CHANGE_REQUEST_INVALIDATED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='injected caught audit failure'; END IF; END");try{assertThatThrownBy(()->guarded(c->{jdbc.update("UPDATE employee SET status='INACTIVE',version=version+1 WHERE id=?",f.employee());try{app.getBean(RequestInvalidator.class).invalidate(c,changes(Set.of(f.employee()),Set.of(),Set.of(),Map.of()),id(),"Fixture caught failure");}catch(RuntimeException ignored){}return true;})).isInstanceOf(RuntimeException.class);}finally{db.execute("DROP TRIGGER be26_caught_audit");}state(request,"PENDING");assertThat(jdbc.queryForObject("SELECT status FROM employee WHERE id=?",String.class,f.employee())).isEqualTo("ACTIVE");assertThat(count("SELECT COUNT(*) FROM relation_change_claim WHERE request_id=?",request)).isEqualTo(1);}
    @Test void hundredSourcesAreOneAtomicCommandAndHundredAndOneAreRejected()throws Exception{var f=data();var systems=new ArrayList<Map<String,Object>>();systems.add(Map.of("systemId",f.system(),"expectedSourceEpoch",0,"expectedVersion",0));for(int n=1;n<100;n++){String s=id();jdbc.update("INSERT INTO business_system(id,code,name,created_at) VALUES(?,?,'Fixture hundred systems',UTC_TIMESTAMP(6))",s,s);systems.add(Map.of("systemId",s,"expectedSourceEpoch",0,"expectedVersion",0));}var in=new LinkedHashMap<>(input(f));in.put("systems",systems);String p=preview(in);var r=close(in,p,id());assertThat(r.statusCode()).as(r.body()).isEqualTo(200);assertThat(body(r).path("updatedSources").size()).isEqualTo(100);assertThat(count("SELECT COUNT(*) FROM authorization_source WHERE employee_id=? AND source_epoch=1 AND source_version=1",f.employee())).isEqualTo(100);systems.add(Map.of("systemId",id(),"expectedSourceEpoch",0,"expectedVersion",0));assertThat(call("/api/v1/admin/source-closure-previews",in,token,null,Map.of()).statusCode()).isEqualTo(422);}
